  function apply(D) {
    if (!D || !D.TEAS) return null;

    D.TEAS.forEach(function (t) {
      var o = TEAS[t.id];
      if (o) t.ar = o;
    });

    if (D.GROUPS) {
      D.GROUPS.forEach(function (g) {
        var o = GROUPS[g.id];
        if (o) g.ar = o;
      });
    }

    if (D.origin) {
      Object.keys(D.origin).forEach(function (id) {
        var c = D.origin[id];
        if (c && COUNTRIES[c.code]) c.ar = COUNTRIES[c.code];
      });
    }

    return D;
  }

  var D = apply(window.TEAFaiData);

  return {
    TEAS: TEAS,
    GROUPS: GROUPS,
    COUNTRIES: COUNTRIES,
    apply: apply,
    sizes: { teas: D ? D.TEAS.length : 0, translated: Object.keys(TEAS).length }
  };
